<?php
require __DIR__.'/../../bootstrap.php';require_role(['SUPER_ADMIN','ADMIN','HOD']);$pdo=Database::connection();$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['_csrf']??null);try{$dept=(int)$_POST['department_id'];$name=trim($_POST['name']);$code=strtoupper(trim($_POST['employee_code']));$email=trim($_POST['email']);$mobile=trim($_POST['mobile']);$designation=trim($_POST['designation']);$qualification=trim($_POST['qualification']);if($name===''||$code===''||$dept<1)throw new RuntimeException('Name, employee code and department are required.');$pdo->beginTransaction();$tmp=bin2hex(random_bytes(4));$u=$pdo->prepare('INSERT INTO users(institution_id,department_id,username,faculty_id,name,email,role,password_hash,active) SELECT institution_id,?,?,?,?,?,?,?,1 FROM departments WHERE id=?');$u->execute([$dept,'FAC-'.$code,$code,$name,$email?:null,'FACULTY',password_hash($tmp,PASSWORD_DEFAULT),$dept]);$uid=(int)$pdo->lastInsertId();$f=$pdo->prepare('INSERT INTO faculty(user_id,employee_code,name,email,mobile,designation,qualification,department_id) VALUES(?,?,?,?,?,?,?,?)');$f->execute([$uid,$code,$name,$email?:null,$mobile?:null,$designation?:null,$qualification?:null,$dept]);$fid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO audit_logs(user_id,action,module,record_id,ip_address) VALUES(?,?,?,?,?)')->execute([user()['id'],'CREATE','FACULTY',$fid,$_SERVER['REMOTE_ADDR']??null]);$pdo->commit();flash('success',"Faculty created. Login ID: FAC-{$code} · Temporary password: {$tmp}");redirect('/faculty/index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException&&$e->getCode()==='23000'?'Employee code, username or email already exists.':$e->getMessage();}}
$rows=$pdo->query('SELECT f.*,d.name department FROM faculty f LEFT JOIN departments d ON d.id=f.department_id ORDER BY f.id DESC')->fetchAll();$departments=$pdo->query('SELECT id,name FROM departments WHERE active=1 ORDER BY name')->fetchAll();$flash=take_flash();$title='Faculty Management';require __DIR__.'/../../views/layout/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="eyebrow">PEOPLE · FACULTY MANAGEMENT</div><h1 class="fw-bold">Faculty.</h1><p class="text-secondary">Faculty accounts and profiles are stored in MySQL.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($flash):?><div class="alert alert-success"><?=e($flash[1])?></div><?php endif;?><div class="row g-4"><div class="col-xl-4"><div class="card table-card p-4"><h5>Add Faculty</h5><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><div class="col-12"><input required name="employee_code" class="form-control" placeholder="Faculty ID"></div><div class="col-12"><input required name="name" class="form-control" placeholder="Full name"></div><div class="col-12"><select required name="department_id" class="form-select"><option value="">Department</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-12"><input name="email" type="email" class="form-control" placeholder="Email"></div><div class="col-12"><input name="mobile" class="form-control" placeholder="Mobile"></div><div class="col-12"><input name="designation" class="form-control" placeholder="Designation"></div><div class="col-12"><input name="qualification" class="form-control" placeholder="Qualification"></div><div class="col-12"><button class="btn btn-primary w-100">Create Faculty Account</button></div></form></div></div><div class="col-xl-8"><div class="card table-card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Faculty</th><th>Faculty ID</th><th>Department</th><th>Designation</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="text-center py-5 text-secondary">No faculty records found.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><div class="small text-secondary"><?=e($r['email']??'')?></div></td><td><?=e($r['employee_code'])?></td><td><?=e($r['department']??'—')?></td><td><?=e($r['designation']??'—')?></td><td><span class="badge text-bg-<?=$r['status']==='ACTIVE'?'success':'secondary'?>"><?=e($r['status'])?></span></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div></div><?php require __DIR__.'/../../views/layout/footer.php';